namespace UniversityCourseCatalog.Models;

public class Course
{
    public int Id { get; set; }
    public string CourseCode { get; set; } = string.Empty;
    public string Title { get; set; } = string.Empty;
    public string Description { get; set; } = string.Empty;
    public int Credits { get; set; }
    public string Schedule { get; set; } = string.Empty;
    public string InstructorName { get; set; } = string.Empty;
    public string InstructorBio { get; set; } = string.Empty;
    public int DepartmentId { get; set; }
    public bool IsFeatured { get; set; }
}

namespace UniversityCourseCatalog.Models;

public class Department
{
    public int Id { get; set; }
    public string Name { get; set; } = string.Empty;
    public string Code { get; set; } = string.Empty;
}

using System.ComponentModel.DataAnnotations;

namespace UniversityCourseCatalog.Models;

public class EnrollmentRequest
{
    [Required(ErrorMessage = "Name is required.")]
    [StringLength(100)]
    public string StudentName { get; set; } = string.Empty;

    [Required(ErrorMessage = "Student ID is required.")]
    [RegularExpression(@"^[A-Z0-9]{6,10}$", ErrorMessage = "Student ID must be 6-10 alphanumeric characters.")]
    public string StudentId { get; set; } = string.Empty;

    [Required(ErrorMessage = "Please select a course.")]
    [Range(1, int.MaxValue, ErrorMessage = "Please select a course.")]
    public int CourseId { get; set; }
}

using UniversityCourseCatalog.Models;

namespace UniversityCourseCatalog.Services;

public class CatalogService
{
    private readonly List<Department> _departments =
    [
        new() { Id = 1, Name = "Computer Science", Code = "CS" },
        new() { Id = 2, Name = "Mathematics", Code = "MATH" },
        new() { Id = 3, Name = "Physics", Code = "PHYS" },
        new() { Id = 4, Name = "English", Code = "ENG" },
        new() { Id = 5, Name = "History", Code = "HIST" }
    ];

    private readonly List<Course> _courses =
    [
        new() { Id = 1, CourseCode = "CS101", Title = "Introduction to Programming", Description = "Learn the fundamentals of programming using C#. Topics include variables, control flow, functions, and object-oriented design principles.", Credits = 3, Schedule = "Mon/Wed/Fri 9:00–9:50 AM", InstructorName = "Dr. Sarah Chen", InstructorBio = "Dr. Chen has 15 years of experience in software engineering and has published extensively on programming pedagogy.", DepartmentId = 1, IsFeatured = true },
        new() { Id = 2, CourseCode = "CS201", Title = "Data Structures and Algorithms", Description = "Study of fundamental data structures (arrays, linked lists, trees, graphs) and algorithm design techniques (divide-and-conquer, dynamic programming, greedy algorithms).", Credits = 4, Schedule = "Tue/Thu 10:30–11:50 AM", InstructorName = "Dr. James Okafor", InstructorBio = "Dr. Okafor specializes in algorithm optimization and has contributed to several open-source projects.", DepartmentId = 1, IsFeatured = true },
        new() { Id = 3, CourseCode = "CS310", Title = "Database Systems", Description = "Principles of database design, SQL, normalization, indexing, and transaction management. Includes hands-on projects with relational databases.", Credits = 3, Schedule = "Mon/Wed 2:00–3:20 PM", InstructorName = "Prof. Maria Lopez", InstructorBio = "Prof. Lopez previously worked as a database architect at a Fortune 500 company before joining academia.", DepartmentId = 1 },
        new() { Id = 4, CourseCode = "MATH101", Title = "Calculus I", Description = "Limits, derivatives, and integrals of single-variable functions. Applications to physics and engineering problems.", Credits = 4, Schedule = "Mon/Wed/Fri 10:00–10:50 AM", InstructorName = "Dr. Robert Kim", InstructorBio = "Dr. Kim is a renowned mathematician whose research focuses on applied analysis and mathematical modeling.", DepartmentId = 2, IsFeatured = true },
        new() { Id = 5, CourseCode = "MATH201", Title = "Linear Algebra", Description = "Vectors, matrices, linear transformations, eigenvalues, and applications in data science and computer graphics.", Credits = 3, Schedule = "Tue/Thu 1:00–2:20 PM", InstructorName = "Dr. Emily Zhang", InstructorBio = "Dr. Zhang's research bridges pure mathematics and machine learning applications.", DepartmentId = 2 },
        new() { Id = 6, CourseCode = "PHYS101", Title = "General Physics I", Description = "Mechanics, thermodynamics, and waves. Includes weekly laboratory sessions with hands-on experiments.", Credits = 4, Schedule = "Tue/Thu 9:00–10:20 AM + Fri Lab 2:00–4:50 PM", InstructorName = "Dr. Alan Patel", InstructorBio = "Dr. Patel is an experimental physicist with research in condensed matter physics.", DepartmentId = 3, IsFeatured = true },
        new() { Id = 7, CourseCode = "PHYS201", Title = "Electromagnetism", Description = "Electric and magnetic fields, Maxwell's equations, electromagnetic waves, and optics.", Credits = 4, Schedule = "Mon/Wed/Fri 11:00–11:50 AM", InstructorName = "Dr. Lisa Nakamura", InstructorBio = "Dr. Nakamura's research on photonics has been published in leading physics journals.", DepartmentId = 3 },
        new() { Id = 8, CourseCode = "ENG101", Title = "Composition and Rhetoric", Description = "Develop critical reading, writing, and argumentation skills. Emphasis on clear academic prose and research-based writing.", Credits = 3, Schedule = "Mon/Wed 9:00–10:20 AM", InstructorName = "Prof. David Brown", InstructorBio = "Prof. Brown is an award-winning author and writing instructor with over 20 years in higher education.", DepartmentId = 4 },
        new() { Id = 9, CourseCode = "ENG220", Title = "American Literature", Description = "Survey of major American literary works from the colonial period to the present, with attention to cultural and historical contexts.", Credits = 3, Schedule = "Tue/Thu 2:30–3:50 PM", InstructorName = "Dr. Angela Rivera", InstructorBio = "Dr. Rivera specializes in 20th-century American fiction and has authored two critical studies.", DepartmentId = 4 },
        new() { Id = 10, CourseCode = "HIST101", Title = "World History to 1500", Description = "Survey of world civilizations from antiquity through the late medieval period, including political, social, and cultural developments.", Credits = 3, Schedule = "Mon/Wed/Fri 1:00–1:50 PM", InstructorName = "Dr. Thomas Wright", InstructorBio = "Dr. Wright is a historian of the ancient world with archaeological fieldwork experience in the Mediterranean.", DepartmentId = 5, IsFeatured = true },
        new() { Id = 11, CourseCode = "HIST202", Title = "Modern European History", Description = "Europe from the Enlightenment to the present: revolutions, industrialization, world wars, and the European Union.", Credits = 3, Schedule = "Tue/Thu 11:00 AM–12:20 PM", InstructorName = "Dr. Katherine Mills", InstructorBio = "Dr. Mills is a specialist in modern European political history and has consulted for documentary filmmakers.", DepartmentId = 5 }
    ];

    public List<Department> GetDepartments() => _departments;

    public Department? GetDepartment(int id) => _departments.FirstOrDefault(d => d.Id == id);

    public List<Course> GetAllCourses() => _courses;

    public List<Course> GetFeaturedCourses() => _courses.Where(c => c.IsFeatured).ToList();

    public Course? GetCourse(int id) => _courses.FirstOrDefault(c => c.Id == id);

    public List<Course> SearchCourses(string? searchTerm, int? departmentId)
    {
        var query = _courses.AsEnumerable();

        if (departmentId.HasValue && departmentId.Value > 0)
        {
            query = query.Where(c => c.DepartmentId == departmentId.Value);
        }

        if (!string.IsNullOrWhiteSpace(searchTerm))
        {
            var term = searchTerm.Trim();
            query = query.Where(c =>
                c.Title.Contains(term, StringComparison.OrdinalIgnoreCase) ||
                c.CourseCode.Contains(term, StringComparison.OrdinalIgnoreCase) ||
                c.InstructorName.Contains(term, StringComparison.OrdinalIgnoreCase));
        }

        return query.ToList();
    }
}

