.nav-links a {
    color: #e8eaf6;
    text-decoration: none;
    font-weight: 500;
}

.nav-links a:hover {
    color: white;
    text-decoration: underline;
}

.content-area {
    flex: 1;
    max-width: 1200px;
    margin: 0 auto;
