@page "/"
@using UniversityCourseCatalog.Services
@using UniversityCourseCatalog.Models
@inject CatalogService Catalog

<PageTitle>University Course Catalog</PageTitle>

<section class="hero">
    <h1>Welcome to the University Course Catalog</h1>
    <p>Explore our departments, discover courses, and enroll for the upcoming semester.</p>
    <a href="/courses" class="btn-primary">Browse All Courses</a>
</section>

<section class="departments-section">
    <h2>Departments</h2>
    <div class="department-grid">
        @foreach (var dept in departments)
        {
            <a href="/courses?departmentId=@dept.Id" class="department-card">
                <h3>@dept.Name</h3>
                <span class="dept-code">@dept.Code</span>
            </a>
        }
    </div>
</section>

<section class="featured-section">
    <h2>Featured Courses</h2>
    <div class="course-grid">
        @foreach (var course in featuredCourses)
        {
            <div class="course-card">
                <span class="course-code">@course.CourseCode</span>
                <h3>@course.Title</h3>
                <p class="credits">@course.Credits credits &middot; @course.InstructorName</p>
                <a href="/courses/@course.Id">View Details →</a>
            </div>
        }
    </div>
</section>

@code {
    private List<Department> departments = [];
    private List<Course> featuredCourses = [];

    protected override void OnInitialized()
    {
        departments = Catalog.GetDepartments();
        featuredCourses = Catalog.GetFeaturedCourses();
    }
}

.hero {
    text-align: center;
    padding: 3rem 1rem;
    background: linear-gradient(135deg, #e8eaf6, #c5cae9);
    border-radius: 8px;
    margin-bottom: 2rem;
}

.hero h1 {
    margin: 0 0 0.5rem;
    color: #1a237e;
}

.hero p {
    color: #37474f;
    font-size: 1.1rem;
    margin-bottom: 1.5rem;
}

.btn-primary {
    display: inline-block;
    background-color: #1a237e;
    color: white;
    padding: 0.75rem 1.5rem;
    border-radius: 4px;
    text-decoration: none;
    font-weight: 600;
}

.btn-primary:hover {
    background-color: #283593;
}

.departments-section, .featured-section {
    margin-bottom: 2.5rem;
}

.departments-section h2, .featured-section h2 {
    color: #1a237e;
    margin-bottom: 1rem;
}

.department-grid {
    display: grid;
    grid-template-columns: repeat(auto-fill, minmax(200px, 1fr));
    gap: 1rem;
}

.department-card {
    display: block;
    padding: 1.25rem;
    border: 1px solid #e0e0e0;
    border-radius: 6px;
    text-decoration: none;
    color: inherit;
    transition: box-shadow 0.2s;
}

.department-card:hover {
    box-shadow: 0 2px 8px rgba(0,0,0,0.12);
}

.department-card h3 {
    margin: 0 0 0.25rem;
    color: #1a237e;
}

.dept-code {
    color: #78909c;
    font-size: 0.9rem;
}

.course-grid {
    display: grid;
    grid-template-columns: repeat(auto-fill, minmax(280px, 1fr));
    gap: 1.25rem;
}

.course-card {
    padding: 1.25rem;
    border: 1px solid #e0e0e0;
    border-radius: 6px;
}

.course-card .course-code {
    display: inline-block;
    background: #e8eaf6;
    color: #1a237e;
    padding: 0.2rem 0.5rem;
    border-radius: 3px;
    font-size: 0.8rem;
    font-weight: 600;
    margin-bottom: 0.5rem;
}

.course-card h3 {
    margin: 0.5rem 0 0.25rem;
    font-size: 1.1rem;
}

.course-card .credits {
    color: #546e7a;
    font-size: 0.9rem;
    margin-bottom: 0.75rem;
}

.course-card a {
    color: #1a237e;
    text-decoration: none;
    font-weight: 500;
}

.course-card a:hover {
    text-decoration: underline;
}

