arguments.new_str:
﻿@page "/"
@using UniversityCourseCatalog.Services
@using UniversityCourseCatalog.Models
@inject CatalogService Catalog

<PageTitle>University Course Catalog</PageTitle>

<section class="hero">
    <h1>Welcome to the University Course Catalog</h1>
    <p>Explore our departments, discover courses, and enroll for the upcoming semester.</p>
    <a href="/courses" class="btn-primary">Browse All Courses</a>
</section>

<section class="departments-section">
    <h2>Departments</h2>
    <div class="department-grid">
        @foreach (var dept in departments)
        {
            <a href="/courses?departmentId=@dept.Id" class="department-card">
                <h3>@dept.Name</h3>
                <span class="dept-code">@dept.Code</span>
            </a>
        }
    </div>
</section>

<section class="featured-section">
    <h2>Featured Courses</h2>
    <div class="course-grid">
        @foreach (var course in featuredCourses)
        {
            <div class="course-card">
                <span class="course-code">@course.CourseCode</span>
                <h3>@course.Title</h3>
                <p class="credits">@course.Credits credits &middot; @course.InstructorName</p>
                <a href="/courses/@course.Id">View Details →</a>
            </div>
        }
    </div>
</section>

@code {
    private List<Department> departments = [];
    private List<Course> featuredCourses = [];

    protected override void OnInitialized()
    {
        departments = Catalog.GetDepartments();
        featuredCourses = Catalog.GetFeaturedCourses();
    }
}

.page {
    display: flex;
    flex-direction: column;
    min-height: 100vh;
}

.top-bar {
    background-color: #1a237e;
    color: white;
    padding: 0;
}

.navbar {
    max-width: 1200px;
    margin: 0 auto;
    display: flex;
    align-items: center;
    justify-content: space-between;
    padding: 1rem 2rem;
}

.brand {
    color: white;
    font-size: 1.3rem;
    font-weight: bold;
    text-decoration: none;
}

.brand:hover {
    color: #e8eaf6;
}

.nav-links {
    list-style: none;
    display: flex;
    gap: 1.5rem;
    margin: 0;
    padding: 0;
}

.nav-links a {
    color: #e8eaf6;
    text-decoration: none;
    font-weight: 500;
}

.nav-links a:hover {
    color: white;
    text-decoration: underline;
}

.content-area {
    flex: 1;
    max-width: 1200px;
    margin: 0 auto;
    padding: 2rem;
    width: 100%;
    box-sizing: border-box;
}

.site-footer {
    background-color: #263238;
    color: #b0bec5;
    text-align: center;
    padding: 1rem 2rem;
    margin-top: 2rem;
}

