toolArgs.file_text:
@page "/courses/{Id:int}"
@using UniversityCourseCatalog.Services
@using UniversityCourseCatalog.Models
@inject CatalogService Catalog

<PageTitle>@(course?.Title ?? "Course Not Found")</PageTitle>

@if (course is null)
{
    <h1>Course Not Found</h1>
    <p>The requested course does not exist.</p>
    <a href="/courses">← Back to Catalog</a>
}
else
{
    <nav class="breadcrumb">
        <a href="/courses">Courses</a> /
        <a href="/courses?departmentId=@course.DepartmentId">@department?.Name</a> /
        <span>@course.CourseCode</span>
    </nav>

    <article class="course-detail">
        <header>
            <span class="course-code">@course.CourseCode</span>
            <h1>@course.Title</h1>
        </header>

        <div class="detail-grid">
            <section class="detail-main">
                <h2>Description</h2>
                <p>@course.Description</p>

                <h2>Instructor</h2>
                <div class="instructor-card">
                    <h3>@course.InstructorName</h3>
                    <p>@course.InstructorBio</p>
                </div>
            </section>

            <aside class="detail-sidebar">
                <div class="info-box">
                    <h3>Course Information</h3>
                    <dl>
                        <dt>Credits</dt>
                        <dd>@course.Credits</dd>
                        <dt>Schedule</dt>
                        <dd>@course.Schedule</dd>
                        <dt>Department</dt>
                        <dd>@department?.Name</dd>
                        <dt>Course Code</dt>
                        <dd>@course.CourseCode</dd>
                    </dl>
                    <a href="/enroll?courseId=@course.Id" class="btn-enroll">Enroll in This Course</a>
                </div>
            </aside>
        </div>
    </article>
}

@code {
    [Parameter] public int Id { get; set; }

    private Course? course;
    private Department? department;

    protected override void OnInitialized()
    {
        course = Catalog.GetCourse(Id);
        if (course is not null)
        {
            department = Catalog.GetDepartment(course.DepartmentId);
        }
    }
}

.breadcrumb {
    margin-bottom: 1.5rem;
    color: #78909c;
}

.breadcrumb a {
    color: #1a237e;
    text-decoration: none;
}

.breadcrumb a:hover {
    text-decoration: underline;
}

.course-detail header {
    margin-bottom: 2rem;
}

.course-detail header .course-code {
    display: inline-block;
    background: #e8eaf6;
    color: #1a237e;
    padding: 0.3rem 0.7rem;
    border-radius: 3px;
    font-size: 0.85rem;
    font-weight: 600;
    margin-bottom: 0.5rem;
}

.course-detail header h1 {
    margin: 0.5rem 0 0;
    color: #1a237e;
}

.detail-grid {
    display: grid;
    grid-template-columns: 1fr 320px;
    gap: 2rem;
}

@media (max-width: 768px) {
    .detail-grid {
        grid-template-columns: 1fr;
    }
}

.detail-main h2 {
    color: #37474f;
    margin-top: 1.5rem;
    margin-bottom: 0.5rem;
}

.detail-main h2:first-child {
    margin-top: 0;
}

.instructor-card {
    background: #f5f5f5;
    padding: 1.25rem;
    border-radius: 6px;
}

.instructor-card h3 {
    margin: 0 0 0.5rem;
    color: #1a237e;
}

.instructor-card p {
    margin: 0;
    color: #546e7a;
}

.info-box {
    background: #fafafa;
    border: 1px solid #e0e0e0;
    border-radius: 6px;
    padding: 1.5rem;
}

.info-box h3 {
    margin: 0 0 1rem;
    color: #1a237e;
}

.info-box dl {
    margin: 0;
}

.info-box dt {
    font-weight: 600;
    color: #37474f;
    margin-top: 0.75rem;
}

.info-box dt:first-child {
    margin-top: 0;
}

.info-box dd {
    margin: 0.25rem 0 0;
    color: #546e7a;
}

.btn-enroll {
    display: block;
    text-align: center;
    margin-top: 1.5rem;
    padding: 0.75rem 1rem;
    background-color: #2e7d32;
    color: white;
    border-radius: 4px;
    text-decoration: none;
    font-weight: 600;
}

.btn-enroll:hover {
    background-color: #388e3c;
}

