+@page "/enroll"
+@using UniversityCourseCatalog.Services
+@using UniversityCourseCatalog.Models
+@using System.ComponentModel.DataAnnotations
+@inject CatalogService Catalog
+
+<PageTitle>Enrollment Request</PageTitle>
+
+<h1>Enrollment Request</h1>
+
+@if (submitted)
+{
+    <div class="success-message">
+        <h2>✓ Request Submitted</h2>
+        <p>Thank you, <strong>@Model.StudentName</strong>! Your enrollment request for
+            <strong>@selectedCourseTitle</strong> has been received.</p>
+        <p>You will receive a confirmation at your university email address.</p>
+        <a href="/courses">← Browse more courses</a>
+    </div>
+}
+else
+{
+    <p class="form-intro">Fill out this form to request enrollment in a course. All fields are required.</p>
+
+    <form method="post" class="enroll-form">
+        <AntiforgeryToken />
+
+        <div class="form-group">
+            <label for="studentName">Full Name</label>
+            <input type="text" id="studentName" name="Model.StudentName" value="@Model.StudentName" />
+            @if (errors.ContainsKey(nameof(Model.StudentName)))
+            {
+                <span class="field-error">@errors[nameof(Model.StudentName)]</span>
+            }
+        </div>
+
+        <div class="form-group">
+            <label for="studentId">Student ID</label>
+            <input type="text" id="studentId" name="Model.StudentId" value="@Model.StudentId"
+                   placeholder="e.g. ABC12345" />
+            @if (errors.ContainsKey(nameof(Model.StudentId)))
+            {
+                <span class="field-error">@errors[nameof(Model.StudentId)]</span>
+            }
+        </div>
+
+        <div class="form-group">
+            <label for="courseId">Course</label>
+            <select id="courseId" name="Model.CourseId">
+                <option value="0">-- Select a course --</option>
+                @foreach (var course in courses)
+                {
+                    <option value="@course.Id" selected="@(Model.CourseId == course.Id)">
+                        @course.CourseCode — @course.Title
+                    </option>
+                }
+            </select>
+            @if (errors.ContainsKey(nameof(Model.CourseId)))
+            {
+                <span class="field-error">@errors[nameof(Model.CourseId)]</span>
+            }
+        </div>
+
+        <button type="submit" class="btn-submit">Submit Enrollment Request</button>
+    </form>
+}
+
+@code {
+    [SupplyParameterFromForm] public EnrollmentRequest Model { get; set; } = new();
+    [SupplyParameterFromQuery] public int? CourseId { get; set; }
+
+    private List<Course> courses = [];
+    private Dictionary<string, string> errors = new();
+    private bool submitted;
+    private string selectedCourseTitle = string.Empty;
+
+    protected override void OnInitialized()
+    {
+        courses = Catalog.GetAllCourses();
+
+        if (CourseId.HasValue && Model.CourseId == 0)
+        {
+            Model.CourseId = CourseId.Value;
+        }
+    }
+
+    protected override void OnParametersSet()
+    {
+        if (!HttpMethods.IsPost(HttpContextAccessor?.HttpContext?.Request.Method ?? "GET"))
+            return;
+
+        errors.Clear();
+        var validationResults = new List<ValidationResult>();
+        var context = new ValidationContext(Model);
+
+        if (!Validator.TryValidateObject(Model, context, validationResults, validateAllProperties: true))
+        {
+            foreach (var result in validationResults)
+            {
+                foreach (var memberName in result.MemberNames)
+                {
+                    errors.TryAdd(memberName, result.ErrorMessage ?? "Invalid value.");
+                }
+            }
+            return;
+        }
+
+        var course = Catalog.GetCourse(Model.CourseId);
+        selectedCourseTitle = course?.Title ?? "Unknown Course";
+        submitted = true;
