.form-intro {
    color: #546e7a;
    margin-bottom: 1.5rem;
}

.enroll-form {
    max-width: 500px;
}

.form-group {
    margin-bottom: 1.25rem;
}

.form-group label {
    display: block;
    font-weight: 600;
    color: #37474f;
    margin-bottom: 0.4rem;
}

.form-group input,
.form-group select {
    width: 100%;
    padding: 0.6rem 0.8rem;
    border: 1px solid #ccc;
    border-radius: 4px;
    font-size: 1rem;
    box-sizing: border-box;
}

.form-group input:focus,
.form-group select:focus {
    outline: none;
    border-color: #1a237e;
    box-shadow: 0 0 0 2px rgba(26, 35, 126, 0.15);
}

.field-error {
    display: block;
    color: #c62828;
    font-size: 0.85rem;
    margin-top: 0.3rem;
}

.btn-submit {
    padding: 0.75rem 1.5rem;
    background-color: #2e7d32;
    color: white;
    border: none;
    border-radius: 4px;
    font-size: 1rem;
    font-weight: 600;
    cursor: pointer;
    margin-top: 0.5rem;
}

.btn-submit:hover {
    background-color: #388e3c;
}

.success-message {
    background: #e8f5e9;
    border: 1px solid #a5d6a7;
    border-radius: 6px;
    padding: 2rem;
    max-width: 500px;
}

.success-message h2 {
    color: #2e7d32;
    margin: 0 0 0.75rem;
}

.success-message p {
    color: #37474f;
    margin: 0.5rem 0;
}

.success-message a {
    display: inline-block;
    margin-top: 1rem;
    color: #1a237e;
    text-decoration: none;
}

.success-message a:hover {
    text-decoration: underline;
}

